(()=>{const division=v=>/women?/i.test(v)?'women':/grom/i.test(v)?'groms':/(men|open)/i.test(v)?'open':'';const normal=v=>String(v).toLowerCase().replace(/women'?s?|men'?s?|groms?|open|qualifiers?|finals?/g,'').replace(/[^a-z0-9]+/g,' ').trim();function suggest(){document.querySelectorAll('.unassigned-race').forEach(row=>{const label=row.querySelector('span'),select=row.querySelector('select');if(!label||!select||select.dataset.suggested)return;const wanted=normal(label.textContent),group=division(label.textContent),matches=[...select.options].filter(o=>normal(o.textContent.split('→').pop())===wanted&&(!group||o.textContent.trim().toLowerCase().startsWith(group)));if(matches.length===1){select.value=matches[0].value;select.dataset.suggested='true';const hint=document.createElement('small');hint.className='suggestion';hint.textContent='Suggested';row.append(hint)}})}new MutationObserver(suggest).observe(document.body,{childList:true,subtree:true});addEventListener('DOMContentLoaded',suggest)})();

